SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
DROP TABLE IF EXISTS `certificates`;
CREATE TABLE `certificates` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `registration_id` int NOT NULL, `course_id` int NOT NULL, `certificate_no` varchar(50) NOT NULL, `qr_code_hash` varchar(100) NOT NULL, `status` enum('requested','returned','being_prepared','awaiting_director_signature','issued','collected','withdrawn') NOT NULL DEFAULT 'requested', `snapshot_name` varchar(150) NOT NULL, `snapshot_course` varchar(150) NOT NULL, `snapshot_duration_months` int NOT NULL, `snapshot_dates` varchar(100) NOT NULL, `taught_skills` text, `tutor_id` int DEFAULT NULL, `tutor_signature_path` varchar(255) DEFAULT NULL, `tutor_name` varchar(150) DEFAULT NULL, `director_id` int DEFAULT NULL, `director_signature_path` varchar(255) DEFAULT NULL, `ceo_name` varchar(150) DEFAULT NULL, `generated_pdf_path` varchar(255) DEFAULT NULL, `issued_at` timestamp NULL DEFAULT NULL, `withdrawn_reason` text, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `certificate_no` (`certificate_no`), UNIQUE KEY `qr_code_hash` (`qr_code_hash`), KEY `idx_cert_registration` (`registration_id`), KEY `idx_cert_course` (`course_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `course_modules`;
CREATE TABLE `course_modules` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `course_id` int NOT NULL, `tutor_id` int DEFAULT NULL, `title` varchar(200) NOT NULL, `description` text, `instructions` text, `video_url` varchar(500) DEFAULT NULL, `order_index` int NOT NULL DEFAULT '0', `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_module_course` (`course_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `directors`;
CREATE TABLE `directors` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `full_name` varchar(150) NOT NULL, `title` varchar(80) NOT NULL DEFAULT 'Director', `signature_path` varchar(255) DEFAULT NULL, `on_certificates` tinyint(1) NOT NULL DEFAULT '0', `is_active` tinyint(1) NOT NULL DEFAULT '1', `created_at` datetime DEFAULT NULL, `updated_at` datetime DEFAULT NULL, PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
