DROP TABLE IF EXISTS `module_contents`;
CREATE TABLE `module_contents` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `module_id` int unsigned NOT NULL, `type` enum('assignment','question','material') NOT NULL, `answer_mode` varchar(20) NOT NULL DEFAULT 'text', `title` varchar(200) NOT NULL, `content` text, `options_json` text, `correct_option` int DEFAULT NULL, `file_path` varchar(255) DEFAULT NULL, `link_url` varchar(500) DEFAULT NULL, `max_score` int DEFAULT NULL, `due_date` date DEFAULT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, `order_index` int NOT NULL DEFAULT '0', PRIMARY KEY (`id`), KEY `idx_content_module` (`module_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `open_submissions`;
CREATE TABLE `open_submissions` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `student_user_id` int NOT NULL, `tutor_id` int DEFAULT NULL, `course_id` int DEFAULT NULL, `title` varchar(150) NOT NULL, `kind` enum('github','drive','file') NOT NULL, `url` varchar(500) DEFAULT NULL, `link_meta` text, `file_path` varchar(255) DEFAULT NULL, `original_name` varchar(255) DEFAULT NULL, `mime` varchar(120) DEFAULT NULL, `bytes` int unsigned DEFAULT NULL, `note` text, `status` enum('submitted','graded','returned') NOT NULL DEFAULT 'submitted', `score` decimal(6,2) DEFAULT NULL, `max_score` decimal(6,2) NOT NULL DEFAULT '100.00', `feedback` text, `graded_by` int DEFAULT NULL, `graded_at` datetime DEFAULT NULL, `submitted_at` datetime NOT NULL, `updated_at` datetime DEFAULT NULL, PRIMARY KEY (`id`), KEY `idx_os_student` (`student_user_id`,`submitted_at`), KEY `idx_os_tutor` (`tutor_id`,`status`,`submitted_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
DROP TABLE IF EXISTS `personal_documents`;
CREATE TABLE `personal_documents` ( `id` int unsigned NOT NULL AUTO_INCREMENT, `user_id` int NOT NULL, `doc_name` varchar(150) NOT NULL, `file_path` varchar(255) NOT NULL, `original_name` varchar(255) DEFAULT NULL, `file_size` int DEFAULT NULL, `uploaded_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_personal_docs_user` (`user_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
